-- Dev-only seed (profile `local`): lets the personas from V100 sign in to the Studio locally.
-- Local credentials are listed in README.md ("Local sign-in"). Secrets are encrypted with the dev-only
-- northline.auth.totp-key from server/auth/src/main/resources/application-local.yml — never valid anywhere else.

-- Registration fields added by V020.
UPDATE identity.users
   SET first_name = split_part(display_name, ' ', 1),
       last_name = substr(display_name, length(split_part(display_name, ' ', 1)) + 2),
       phone_verified_at = created_at,
       terms_version = '3.0',
       terms_accepted_at = created_at
 WHERE id IN ('01J9ZD3V00000000000000RAV1', '01J9ZD3V000000000000000JAS', '01J9ZD3V00000000000000PR1Y');

